function translate(root=document.body){if(lang!=="en")return;document.documentElement.lang="en";document.documentElement.dir="ltr";const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode())translateNode(n);$$("input[placeholder],textarea[placeholder],[title],[aria-label]",root).forEach(el=>{for(const a of ["placeholder","title","aria-label"]){const v=el.getAttribute(a);if(v&&I18N.en[v])el.setAttribute(a,I18N.en[v])}})}
